  bool menuMapsReady;
  IEnumerator ScanMenuMaps(int menuScreen,Text message){yield return null;var result=new List<MapInfo>();foreach(var root in new[]{Path.Combine(Application.streamingAssetsPath,"Maps"),Path.Combine(Storage.Root,"Maps")}){string[] folders;try{folders=Directory.Exists(root)?Directory.GetDirectories(root):new string[0];}catch(Exception e){Debug.LogWarning(e);continue;}foreach(var folder in folders){if(screen!=menuScreen)yield break;if(Path.GetFileName(folder).StartsWith("_"))continue;try{result.Add(MapCatalog.Read(folder));}catch(Exception e){Debug.LogWarning(e);if(message)message.text="部分地图未能读取，可重新导入。";}yield return null;}}if(screen==menuScreen){maps=result;menuMapsReady=true;if(message)message.text=result.Count==0?"请先导入地图，再开始驾驶。":"已就绪 · "+result.Count+" 张地图";Debug.Log("RAIL_STARTUP_MENU_READY maps="+result.Count);}}
  void ChooseMap(){Clear("选择地图");if(maps.Count==0)Label("尚未找到有效地图包。");foreach(var m in maps){var map=m;Button(map.Name,()=>{current=map;selection=new RunPlan{mapId=map.manifest.id,routeId=map.route.id,start=0,end=map.route.loop?0:map.route.stations.Length-1,selected=Enumerable.Repeat(true,map.route.stations.Length).ToArray(),train=cfg.train.Copy()};RouteMenu();});}Button("返回",Menu);}
  void RouteMenu(){Clear("交路与停靠站");var r=SelectedSource();Label(current.Name+"\n"+r.name+"；起终点相同表示运行完整一圈。",20);
   if(current.routes.Length>1)Button("切换线路方向",()=>{var next=current.routes[(Array.IndexOf(current.routes,r)+1)%current.routes.Length];string from=r.stations[selection.start].id,to=r.stations[selection.end].id;var choices=r.stations.Select((st,i)=>new{st.id,value=selection.selected[i]}).ToDictionary(x=>x.id,x=>x.value);selection.routeId=next.id;selection.start=Array.FindIndex(next.stations,x=>x.id==from);selection.end=Array.FindIndex(next.stations,x=>x.id==to);selection.selected=next.stations.Select(st=>choices.ContainsKey(st.id)?choices[st.id]:true).ToArray();RouteMenu();});
   Button("起点："+r.stations[selection.start].Display,()=>{Clear("选择起点");for(int i=0;i<(r.loop?r.stations.Length:selection.end);i++){int n=i;Button(r.stations[i].Display,()=>{selection.start=n;RouteMenu();});}Button("返回",RouteMenu);});
   Button("终点："+r.stations[selection.end].Display,()=>{Clear("选择终点");for(int i=r.loop?0:selection.start+1;i<r.stations.Length;i++){int n=i;Button(r.stations[i].Display,()=>{selection.end=n;RouteMenu();});}Button("返回",RouteMenu);});
   Label("起终点固定停靠；未勾选中间站直接通过，无通过限速。",18);var order=JourneyPlanner.Order(r,selection.start,selection.end);for(int j=0;j<order.Length;j++){int n=order[j];bool endpoint=j==0||j==order.Length-1;Button((endpoint||selection.selected[n]?"☑ ":"☐ ")+r.stations[n].Display+(endpoint?"  [固定]":""),()=>{if(!endpoint)selection.selected[n]=!selection.selected[n];RouteMenu();});}
   Button("取消所有中间停靠",()=>{foreach(int i in order)selection.selected[i]=false;RouteMenu();});Button("全选",()=>{foreach(int i in order)selection.selected[i]=true;RouteMenu();});Button("下一步：运行环境",EnvironmentMenu);Button("返回地图",ChooseMap);}
  void EnvironmentMenu(){Clear("运行环境");Button("车型："+selection.train.name,()=>TrainSettings(()=>{selection.train=cfg.train.Copy();EnvironmentMenu();}));Button("难度："+new[]{"普通","高难度","拟真"}[(int)selection.difficulty],()=>{selection.difficulty=(Difficulty)(((int)selection.difficulty+1)%3);EnvironmentMenu();});Label("普通：加减速、手动门；高难度：运行中按住警惕按钮。\n拟真：另需启车确认、方向及门侧选择；雨天附着、灯光和雨刷。",18);Button("天气："+selection.weather,()=>{var a=new[]{"晴","阴","雨"};selection.weather=a[(Array.IndexOf(a,selection.weather)+1)%3];EnvironmentMenu();});Button("时段："+selection.time,()=>{var a=new[]{"清晨","白天","傍晚","夜间"};selection.time=a[(Array.IndexOf(a,selection.time)+1)%4];EnvironmentMenu();});Button("开始驾驶",()=>StartRun(selection,null));Button("返回",RouteMenu);}
  void TrainSettings(Action back){Clear("车辆性能 — 下一交路生效");Button("选择已保存的性能预设",()=>{Clear("性能预设");foreach(var preset in (cfg.presets??new List<TrainSpec>())){var item=preset;Button(item.name,()=>{cfg.train=item.Copy();cfg.Save();TrainSettings(back);});}Button("返回",()=>TrainSettings(back));});var t=cfg.train;var name=Field("配置名称",t.name);var max=Field("最高速度 km/h",t.maxSpeedKmh.ToString());var length=Field("编组长度 m（停站需要全列在站台内）",t.length.ToString());var power=Field("牵引各档 m/s²，逗号分隔，第一项为0",string.Join(",",t.power.Select(x=>x.ToString(System.Globalization.CultureInfo.InvariantCulture))));var brake=Field("制动各档 m/s²，第一项为0",string.Join(",",t.brake.Select(x=>x.ToString(System.Globalization.CultureInfo.InvariantCulture))));var eb=Field("紧急制动 m/s²",t.emergency.ToString());var response=Field("响应时间 s",t.response.ToString());var coast=Field("惰行减速度 m/s²",t.coast.ToString());Button("保存性能配置",()=>{var n=new TrainSpec{name=name.text,maxSpeedKmh=Num(max.text),length=Num(length.text),power=power.text.Split(',').Select(Num).ToArray(),brake=brake.text.Split(',').Select(Num).ToArray(),emergency=Num(eb.text),response=Num(response.text),coast=Num(coast.text)};n.Validate();cfg.train=n;cfg.SavePreset();back();});Button("恢复预设",()=>{cfg.train=new TrainSpec();cfg.Save();TrainSettings(back);});var path=Field("性能 JSON 导入/导出绝对路径",Path.Combine(Storage.Root,"train.json"));Button("导出当前配置",()=>{File.WriteAllText(path.text,JsonUtility.ToJson(cfg.train,true));});Button("导入配置",()=>{var n=JsonUtility.FromJson<TrainSpec>(File.ReadAllText(path.text));n.Validate();cfg.train=n;cfg.SavePreset();TrainSettings(back);});Button("返回",back);}
  static double Num(string s){return double.Parse(s,System.Globalization.CultureInfo.InvariantCulture);}
  void Settings(Action back){if(Mobile){MobileSettings(back);return;}Clear("设置与键盘");Button("画质："+new[]{"标准","高画质","极端","极端（高）"}[cfg.quality],()=>{cfg.quality=(cfg.quality+1)%4;ApplyQuality();cfg.Save();Settings(back);});Button("音量："+Mathf.RoundToInt(cfg.volume*100)+"%",()=>{cfg.volume=(cfg.volume+.1f)%1.1f;cfg.Save();Settings(back);});Button("视角灵敏度："+cfg.sensitivity.ToString("F1"),()=>{cfg.sensitivity=cfg.sensitivity>=3?.5f:cfg.sensitivity+.5f;cfg.Save();Settings(back);});Label("Esc 固定暂停/返回。点击动作后按新键；重复键不会被接受。",18);foreach(var b in cfg.bindings){var bind=b;Button(bind.action+"  ["+bind.key+"]",()=>{rebind=bind.action;Clear("按下新的键："+rebind);Label("Esc 取消。",20);});}Button("恢复默认按键",()=>{cfg.bindings=new GameConfig().bindings;cfg.Save();Settings(back);});Button("返回",back);}
  void ImportMenu(){if(Mobile){IOSImportMenu();return;}Clear("导入地图");Label("选择 .railmap 地图包。导入时显示进度；同ID旧版本会先备份。",20);var path=Field("地图包绝对路径（也可粘贴）","/Volumes/KINGSTON/RailDrivingSimulator/CityLoop_FullV2.railmap");Button("浏览文件…",()=>{var selected=NativeMapPicker.Choose();if(!string.IsNullOrEmpty(selected))path.text=selected;});Button("校验并导入",()=>StartCoroutine(ImportMap(path.text.Trim())));Button("返回",Menu);}
  IEnumerator ImportMap(string path){loading=true;Clear("校验并导入地图");status=Label("准备导入……",20);MapImportJob job=null;try{job=new MapImportJob(path,Path.Combine(Storage.Root,"Maps"));activeImport=job;}catch(Exception ex){loading=false;CleanPickedFile();Error(ex.Message);yield break;}var cancel=new System.Threading.CancellationTokenSource();Task task=null;Button("取消导入",()=>{cancel.Cancel();if(task!=null)StartCoroutine(CleanupImportTask(task,pickedTemp));pickedTemp=null;activeImport=null;loading=false;Clear("已取消导入");Label("临时文件正在后台清理。",20);Button("返回菜单",Menu);});int importScreen=screen;task=Task.Run(()=>job.Extract(cancel.Token),cancel.Token);float start=Time.realtimeSinceStartup;while(!task.IsCompleted){if(cancel.IsCancellationRequested||screen!=importScreen){cancel.Cancel();yield break;}if(status)status.text=job.Progress()+"\n已用时 "+(Time.realtimeSinceStartup-start).ToString("F0")+" 秒；可随时取消。";yield return null;}if(screen!=importScreen)yield break;loading=false;if(task.IsCanceled){ImportMenu();yield break;}if(task.IsFaulted){CleanPickedFile();activeImport=null;Error(task.Exception.GetBaseException().Message);yield break;}status.text="校验线路元数据并安装……";yield return null;try{var installed=job.Commit();maps=MapCatalog.Discover();Clear("地图导入成功");Label(installed.Name);Button("返回菜单",Menu);}catch(Exception ex){Error(ex.Message);}cancel.Dispose();activeImport=null;CleanPickedFile();}
  RouteData Journey(RunPlan p,out RunPlan compiled){var source=current.routes.FirstOrDefault(r=>r.id==p.routeId);if(source==null)throw new IOException("线路方向未安装");return JourneyPlanner.Compile(source,p,out compiled);}
  void StartRun(RunPlan p,RunState saved){RunPlan compiled;var route=Journey(p,out compiled);var check=new Simulation(route,compiled);if(saved!=null)check.Restore(saved);StartCoroutine(Begin(p,saved));}
  IEnumerator Begin(RunPlan p,RunState saved){paused=true;loading=true;Clear("载入线路");status=Label("准备全量地图分区资源……");if(world)Destroy(world.gameObject);if(train)Destroy(train);yield return null;ApplyQuality();RunPlan compiled;var route=Journey(p,out compiled);sim=new Simulation(route,compiled);sim.state.mapFingerprint=current.manifest.sourceFingerprint;if(saved!=null)sim.Restore(saved);world=new GameObject("分区地图").AddComponent<MapWorld>();yield return world.Initialize(current);if(world.error!=null){loading=false;Error(world.error);yield break;}var pose=sim.route.Pose(sim.state.s);origin=new Vector3((float)pose.x,0,(float)pose.z);world.Follow(Pos(pose),origin);while(!world.NeededReady(Pos(pose))&&world.error==null){status.text="正在加载附近轨道、站台与建筑……";yield return null;}if(world.error!=null){loading=false;Error(world.error);yield break;}var prefab=Resources.Load<GameObject>("Train/E235Cab");if(!prefab){loading=false;Error("车辆资源未完整打包，请重新构建游戏");yield break;}train=new GameObject("玩家列车");var visual=Instantiate(prefab,train.transform);visual.transform.localRotation=Quaternion.Euler(0,180,0);if(scenery)Destroy(scenery.gameObject);scenery=new GameObject("邻线背景列车").AddComponent<SceneryTrain>();scenery.transform.SetParent(world.transform);scenery.Initialize(world);if(current.routes.Length>1)scenery.UseTrack(current.routes.First(r=>r.id!=p.routeId));if(traffic)Destroy(traffic.gameObject);traffic=new GameObject("道路车辆").AddComponent<RoadTraffic>();traffic.Initialize(world);sounds.Initialize();SetEnvironment();if(effects){effects.Cleanup();Destroy(effects);}effects=gameObject.AddComponent<Effects>();effects.Configure(cam,p.weather=="雨",p.time=="夜间",cfg.quality);heading=Quaternion.LookRotation(Pos(sim.route.Pose(sim.state.s+5))-Pos(sim.route.Pose(sim.state.s-5)),Vector3.up);yaw=pitch=0;external=false;loading=false;DrivingUI();paused=saved!=null;if(paused)Pause();}
  static Vector3 Pos(TrackPoint p){return new Vector3((float)p.x,(float)p.y,(float)p.z);}
  void DrivingUI(){ResetUI();var bg=new GameObject("运行状态",typeof(RectTransform),typeof(Image)).GetComponent<RectTransform>();bg.SetParent(canvas.transform,false);bg.anchorMin=Vector2.zero;bg.anchorMax=new Vector2(1,.165f);bg.offsetMin=bg.offsetMax=Vector2.zero;bg.GetComponent<Image>().color=new Color(.025f,.035f,.045f,.91f);hud=Label("",25,bg);hud.rectTransform.anchorMin=Vector2.zero;hud.rectTransform.anchorMax=Vector2.one;hud.rectTransform.offsetMin=new Vector2(24,8);hud.rectTransform.offsetMax=new Vector2(-24,-8);hud.alignment=TextAnchor.MiddleLeft;paused=false;if(Mobile)TouchDrivingUI();}
  void Pause(){waitingVigilance=false;MobileInput.Clear();paused=true;Clear("暂停");Button("继续驾驶",()=>DrivingUI());Button("保存当前交路",()=>{Storage.Write("run.json",JsonUtility.ToJson(sim.state,true));Pause();Label("已保存；继续存档时以暂停状态恢复。",18);});Button("重新定位到目标站前",()=>{sim.ResetApproach();DrivingUI();});Button("放弃当前中间站停靠",()=>{Clear("确认放弃停靠？");Label(sim.Next==null?"无目标站":sim.Next.Display+"\n这是玩家主动决定，不会自动跳站。");Button("确认放弃",()=>{sim.AbandonNext();Pause();Label(sim.Message,18);});Button("取消",Pause);});Button("设置",()=>Settings(Pause));Button("回到主菜单",()=>{if(world)Destroy(world.gameObject);if(train)Destroy(train);sim=null;sounds.Stop();Menu();});}
  void ResumeSave(){var text=Storage.Read("run.json");if(text==null)throw new IOException("还没有手动存档");var saved=JsonUtility.FromJson<RunState>(text);current=maps.Find(m=>m.manifest.id==saved.plan.mapId);if(current==null||current.manifest.sourceFingerprint!=saved.mapFingerprint||!current.routes.Any(r=>r.id==saved.plan.routeId))throw new IOException("存档所用地图版本未安装或已经改变");StartRun(saved.plan,saved);}
  void Update(){if(Mobile)MobileFrame();avgFrame=Mathf.Lerp(avgFrame,Time.unscaledDeltaTime,.04f);perfClock+=Time.unscaledDeltaTime;if(cfg.quality==2&&(!paused||renderSweep)&&perfClock>5){perfClock=0;var pipe=GraphicsSettings.currentRenderPipeline as UnityEngine.Rendering.Universal.UniversalRenderPipelineAsset;if(pipe)pipe.renderScale=Mathf.Clamp(pipe.renderScale+(avgFrame>(Mobile?1f/28:1f/30)?-.05f:avgFrame<(Mobile?1f/29.5f:1f/40)?.025f:0),Mobile?.65f:.70f,Mobile?.88f:1);}
