 IEnumerator FullStationTour(string dir){cfg.quality=2;ApplyQuality();foreach(var source in current.routes){var p=new RunPlan{mapId=current.manifest.id,routeId=source.id,start=0,end=0,selected=Enumerable.Repeat(true,source.stations.Length).ToArray()};yield return Begin(p,null);paused=true;external=true;foreach(var r in train.GetComponentsInChildren<Renderer>())r.enabled=false;for(int i=1;i<sim.route.stations.Length;i++){var st=sim.route.stations[i];sim.state.s=Math.Max(0,st.platformStartS-90);world.Follow(Pos(sim.route.Pose(sim.state.s)),origin);float since=Time.realtimeSinceStartup;while(!world.NeededReady(Pos(sim.route.Pose(sim.state.s)))){world.Follow(Pos(sim.route.Pose(sim.state.s)),origin);if(Time.realtimeSinceStartup-since>90)throw new Exception("Station stream timeout");yield return null;}yaw=pitch=0;yield return new WaitForSeconds(.8f);ScreenCapture.CaptureScreenshot(Path.Combine(dir,"station_"+source.id+"_"+i.ToString("00")+".png"));yield return new WaitForSeconds(.2f);File.AppendAllText(Path.Combine(dir,"station_tour.txt"),"STATION_VIEW_PASS route="+source.id+" station="+st.id+" renderers="+world.GetComponentsInChildren<MeshRenderer>().Length+" memory_mb="+(UnityEngine.Profiling.Profiler.GetTotalAllocatedMemoryLong()/1048576)+"\n");}}}
 IEnumerator RenderBothDirections(string dir){cfg.quality=2;ApplyQuality();foreach(var source in current.routes){var p=new RunPlan{mapId=current.manifest.id,routeId=source.id,start=0,end=0,selected=Enumerable.Repeat(true,source.stations.Length).ToArray()};yield return Begin(p,null);yield return RenderSweep(dir);File.Copy(Path.Combine(dir,"render_drive.txt"),Path.Combine(dir,"render_drive_"+source.id+".txt"),true);}}
 IEnumerator RenderSweep(string dir){renderSweep=true;paused=true;external=false;foreach(var r in train.GetComponentsInChildren<Renderer>())r.enabled=true;sim.state.s=350;sim.state.v=Environment.GetCommandLineArgs().Contains("--fast-route-test")?60:22;sim.state.a=0;sim.Neutral();yaw=pitch=0;float started=Time.realtimeSinceStartup,waiting=0;var times=new List<float>();while(sim.state.s<sim.route.Length-50){var p=Pos(sim.route.Pose(sim.state.s));world.Follow(p,origin);float dt=Mathf.Min(Time.unscaledDeltaTime,.1f);if(world.NeededReady(p))sim.state.s+= (Environment.GetCommandLineArgs().Contains("--fast-route-test")?60:22)*dt;else waiting+=Time.unscaledDeltaTime;times.Add(Time.unscaledDeltaTime);yield return null;}times.Sort();float duration=Time.realtimeSinceStartup-started;string result="RENDER_DRIVE_PASS quality=2 distance_m="+(sim.state.s-350).ToString("F1")+" frames="+times.Count+" seconds="+duration.ToString("F3")+" avg_fps="+(times.Count/duration).ToString("F2")+" p95_frame_ms="+(times[(int)(times.Count*.95)]*1000).ToString("F2")+" max_frame_ms="+(times.Last()*1000).ToString("F2")+" stream_wait_s="+waiting.ToString("F2")+" GPU="+SystemInfo.graphicsDeviceName;File.WriteAllText(Path.Combine(dir,"render_drive.txt"),result);ScreenCapture.CaptureScreenshot(Path.Combine(dir,"station_final.png"));yield return new WaitForSeconds(.3f);renderSweep=false;}
 void Commands(){if(cfg.Down("牵引增档"))sim.ChangeNotch(1);if(cfg.Down("制动增档"))sim.ChangeNotch(-1);if(cfg.Down("惰行"))sim.Neutral();if(cfg.Down("紧急制动"))sim.Emergency();if(cfg.Down("紧急复位"))sim.ResetEmergency();if(cfg.Down("开门"))sim.OpenDoor();if(cfg.Down("关门"))sim.CloseDoor();if(cfg.Down("开门侧左"))sim.state.doorSide="left";if(cfg.Down("开门侧右"))sim.state.doorSide="right";if(cfg.Down("启车确认")){sim.state.initialized=true;sim.Message="启车确认完成";}if(cfg.Down("方向前进"))sim.SetReverser(1);if(cfg.Down("方向中立"))sim.SetReverser(0);if(cfg.Down("方向后退"))sim.SetReverser(-1);if(cfg.Down("切换视角")){external=!external;foreach(var r in train.GetComponentsInChildren<Renderer>())r.enabled=!external;}if(cfg.Down("视角归正"))yaw=pitch=0;if(cfg.Down("HUD"))showHud=!showHud;if(cfg.Down("雨刷"))sim.state.wiper=!sim.state.wiper;if(cfg.Down("前照灯"))sim.state.lights=!sim.state.lights;}
  void AtmosphereGlobals(){var direction=-sun.transform.forward;var viewport=cam.WorldToViewportPoint(cam.transform.position+direction*10000);Shader.SetGlobalVector("_RailSunScreen",viewport);Shader.SetGlobalVector("_RailSunDirection",direction);Shader.SetGlobalVector("_RailSunColor",sun.color);Shader.SetGlobalFloat("_RailSunPower",sun.intensity);Shader.SetGlobalVector("_RailOrigin",origin);}
  void PoseTrain(){var p=Pos(sim.route.Pose(sim.state.s));if(Vector3.Distance(new Vector3(p.x,0,p.z),origin)>1000)origin=new Vector3(p.x,0,p.z);world.origin=origin;world.transform.position=-origin;var a=Pos(sim.route.Pose(sim.state.s-6));var b=Pos(sim.route.Pose(sim.state.s+6));var target=Quaternion.LookRotation((b-a).normalized,Vector3.up);heading=Quaternion.Slerp(heading,target,1-Mathf.Exp(-Time.unscaledDeltaTime*8));train.transform.SetPositionAndRotation(p-origin,heading);cam.transform.SetPositionAndRotation(p-origin+heading*new Vector3(0,2.7f,0),heading*Quaternion.Euler(pitch,yaw,0));}
  void OnApplicationFocus(bool focus){if(!focus&&sim!=null&&!paused&&!loading)Pause();}
  void ApplyQuality(){Shader.SetGlobalFloat("_RailQuality",cfg.quality);QualitySettings.vSyncCount=0;QualitySettings.shadowDistance=new[]{180,350,650,900}[cfg.quality];QualitySettings.globalTextureMipmapLimit=cfg.quality==0?1:0;QualitySettings.anisotropicFiltering=AnisotropicFiltering.ForceEnable;var pipeline=GraphicsSettings.currentRenderPipeline as UnityEngine.Rendering.Universal.UniversalRenderPipelineAsset;if(pipeline){pipeline.upscalingFilter=UnityEngine.Rendering.Universal.UpscalingFilterSelection.FSR;pipeline.fsrOverrideSharpness=true;pipeline.fsrSharpness=.55f;pipeline.renderScale=cfg.quality==2?.9f:1;pipeline.shadowDistance=QualitySettings.shadowDistance;pipeline.mainLightShadowmapResolution=new[]{2048,4096,8192,8192}[cfg.quality];pipeline.cascade4Split=new Vector3(.06f,.20f,.48f);pipeline.shadowCascadeCount=cfg.quality==0?2:4;}if(Mobile)MobileQuality(pipeline);if(effects&&sim!=null)effects.Configure(cam,sim.state.plan.weather=="雨",sim.state.plan.time=="夜间",cfg.quality);var rendererData=Resources.FindObjectsOfTypeAll<UnityEngine.Rendering.Universal.UniversalRendererData>().FirstOrDefault();if(rendererData)foreach(var feature in rendererData.rendererFeatures)if(feature is UnityEngine.Rendering.Universal.ScreenSpaceAmbientOcclusion)feature.SetActive(cfg.quality>=2);AudioListener.volume=1;}
  void SetEnvironment(){bool night=sim.state.plan.time=="夜间",rain=sim.state.plan.weather=="雨",low=sim.state.plan.time=="清晨"||sim.state.plan.time=="傍晚";sun.transform.rotation=Quaternion.Euler(night?175:low?12:48,sim.state.plan.time=="清晨"?-90:sim.state.plan.time=="傍晚"?90:-35,0);sun.intensity=night?.03f:rain?.5f:1.7f;sun.color=low?new Color(1,.77f,.5f):Color.white;var sky=new Material(Shader.Find("Skybox/Procedural"));sky.EnableKeyword("_SUNDISK_HIGH_QUALITY");sky.SetFloat("_SunSize",.015f);sky.SetFloat("_AtmosphereThickness",rain?1.5f:1);sky.SetFloat("_Exposure",night?.035f:1.1f);sky.SetColor("_SkyTint",rain?new Color(.48f,.5f,.53f):new Color(.5f,.55f,.63f));RenderSettings.skybox=sky;RenderSettings.sun=sun;cam.clearFlags=CameraClearFlags.Skybox;RenderSettings.ambientMode=AmbientMode.Trilight;RenderSettings.ambientSkyColor=night?new Color(.04f,.055f,.08f):rain?new Color(.32f,.36f,.40f):new Color(.45f,.58f,.75f);RenderSettings.ambientEquatorColor=night?new Color(.035f,.04f,.055f):new Color(.30f,.32f,.35f);RenderSettings.ambientGroundColor=new Color(.13f,.14f,.16f);RenderSettings.fog=true;RenderSettings.fogMode=FogMode.ExponentialSquared;RenderSettings.fogDensity=rain?.00048f:.00017f;RenderSettings.fogColor=night?new Color(.025f,.03f,.04f):rain?new Color(.48f,.52f,.55f):new Color(.67f,.77f,.84f);cam.backgroundColor=RenderSettings.fogColor;Shader.SetGlobalFloat("_RailWetness",rain?1:0);Shader.SetGlobalFloat("_RailNight",night?1:0);Shader.SetGlobalFloat("_RailCloudCoverage",rain?.78f:sim.state.plan.weather=="阴"?.64f:.49f);Shader.SetGlobalFloat("_RailFogDensity",rain?.0013f:low?.0032f:.00055f);DynamicGI.UpdateEnvironment();}
